    @com.fasterxml.jackson.annotation.JsonProperty("keep_index_refresh_interval")
    val keepIndexRefreshInterval: Boolean? = null,
) : DatabaseConfigConfig, DatabaseConfigResponseConfig

/**
 * System-wide settings for the pgaudit extension. When `feature_enabled` is true, the pgaudit
 * extension is automatically installed. When false, the extension is uninstalled but auditing
 * configurations (such as `log`) are preserved.
 */
data class PostgresAdvancedConfigPgaudit(
    /**
     * Enable pgaudit extension. When enabled, pgaudit extension will be automatically installed.
     * Otherwise, extension will be uninstalled but auditing configurations will be preserved.
     */
    @com.fasterxml.jackson.annotation.JsonProperty("feature_enabled")
    val featureEnabled: Boolean? = null,
    /**
     * Specifies which classes of statements will be logged by session audit logging. Available
     * values are `read` (SELECT and COPY when the source is a relation or query), `write` (INSERT,
     * UPDATE, DELETE, TRUNCATE, and COPY when the destination is a relation), `function` (function
     * calls and DO blocks), `role` (statements related to roles and privileges: GRANT, REVOKE,
     * CREATE/ALTER/DROP ROLE), `ddl` (all DDL that is not included in the role class), `misc`
     * (miscellaneous commands,…
     */
    val log: List<PostgresAdvancedConfigPgauditLogItemEnum>? = null,
)
